local _check_ios_path_valid = function(path, _storage_type)
    if DST.is_log_allow_with_level(DST.INNER_LOG_LEVEL.DEBUG) then
        -- 以下检查会耗时，这里在非debug下不开启
        return
    end

    -- 如果ios 平台，检查私有路径下的path前缀需要在白名单
    if cur_os == "ios" and path then
        local tmp_path = path
        if _storage_type == M.STORAGE_TYPE.EXTERNAL_OTHER then
            -- ios 无外部存储路径，只有内部存储路径，所以这里取INTERNAL_APP_PRIVATE
            local _base_path = ERB.static_get_storage_path_by_type(M.STORAGE_TYPE.INTERNAL_APP_PRIVATE)
            local _begin, _end = path:find(_base_path, 1, true)
            if _end then
                if _end < string.len(path) then
                    tmp_path = path:sub(_end + 1)
                else
                    tmp_path = ''
                end
            end
            --_ejoysdk.log("get_file_dest_info_with_params >> b:" .. tostring(_base_path) .. ", tmp:" .. tostring(tmp_path) .. ", path:" .. tostring(path))
        end

        tmp_path = E.Path.trim_begin_separator(tmp_path)
        local is_prefix_valid = false
        for _, wp in ipairs(IOS_RELA_PATH_WHITE_PREFIX) do
            if E.Utils.start_with(tmp_path, wp) then
                is_prefix_valid = true
                break
            end
        end

        assert(is_prefix_valid, "dest_path in ios inner storage directory should begin with 'Documents', 'Library', 'tmp', current storage type:" .. tostring(_storage_type) .. ", path:" .. tostring(path))
    end
end

function M._test_check_ios_path_valid(path, _storage_type)
    return _check_ios_path_valid(path, _storage_type)
end

-- @param path: is same with file_ext.dest_path
local function get_file_dest_info_with_params(url, path, name, _storage_type)
    -- if storage type is external_other, then path should not be nil. if it's nil then the full path is not complete
    assert(_storage_type ~= M.STORAGE_TYPE.EXTERNAL_OTHER or (_storage_type == M.STORAGE_TYPE.EXTERNAL_OTHER and path), "storage is set to external_other, so dest_path should NOT be nil!!!, storage:" .. tostring(_storage_type) .. ", path:" .. tostring(path))
    -- check ios path valid
    _check_ios_path_valid(path, _storage_type)

    local file_info = {}
    file_info[M.FILE_DEST_INFO_KEY.URL] = url

    --_ejoysdk.log("get_file_dest_info_with_params >> path:" .. tostring(path))
    local dest_file_name
    if not name or name == "" then
        dest_file_name = guess_file_name_from_url(url)
        -- 输出日志添加条件判断主要因为这里的字符串拼接在大文件列表也是耗时的，以下同样原因
        if DST.is_log_allow_with_level(DST.INNER_LOG_LEVEL.DEBUG) then
            DST.log_debug(TAG, "gen_task_id check file name empty, now guess from url:" .. tostring(url) .. ", " .. tostring(dest_file_name))
        end
    else
        dest_file_name = name
    end
    file_info[M.FILE_DEST_INFO_KEY.NAME] = dest_file_name

    -- dest_path
    local dest_path = path
    if dest_path == nil then
        if cur_os == 'ios' then
            dest_path = DEFAULT_IOS_CACHED_PATH_NAME
        else
            dest_path = DEFAULT_CACHED_PATH_NAME
        end
    end

    dest_path = E.Utils.trim_end(dest_path, "/")
    local dest_path_relative = dest_path
    -- update dest rela path
    local dest_file_path_relative = dest_path_relative .. "/" .. dest_file_name

    -- get storage path
    local storage_type = _storage_type or DEFAULT_STORAGE_TYPE
    -- the storage_path is the root path for the specified storage type
    local storage_path = ERB.static_get_storage_path_by_type(storage_type)
    if storage_path then
        if dest_path and dest_path ~= '' then
            --- Document, Cache, Library
            dest_path = E.Path.trim_begin_separator(dest_path)
            dest_path = storage_path .. "/" .. dest_path
        else
            dest_path = storage_path
        end
    end

    -- dest_file_path = storage_path + dest_file_rela_path
    file_info[M.FILE_DEST_INFO_KEY.STORAGE_PATH] = storage_path
    file_info[M.FILE_DEST_INFO_KEY.DEST_RELA_PATH] = dest_file_path_relative
    file_info[M.FILE_DEST_INFO_KEY.DEST_FILE_DIR] = dest_path
    file_info[M.FILE_DEST_INFO_KEY.DEST_FILE_PATH] = dest_path .. "/" .. dest_file_name
    --_ejoysdk.log("get_file_dest_info_with_params: storage_type:" .. tostring(storage_type) .. ", storage_path:" .. tostring(storage_path) .. ", dest_path:" .. tostring(dest_path))
    if DST.is_log_allow_with_level(DST.INNER_LOG_LEVEL.DEBUG) then
        DST.log_debug(TAG, "get_file_dest_info_with_params: storage_type:" .. tostring(storage_type) .. ", storage_path:" .. tostring(storage_path) .. ", dest_path:" .. tostring(dest_path))
    end
    -- iOS增加一个额外的字段
    if cur_os == "ios" and storage_path then
        -- iOS用删除了应用标识的字符串来处理，方便调试和测试，不然每次Xcode启动APP，应用标识都不一样，文件的绝对路径就变了
        local temp = M.get_parent_folder(storage_path)
        local dest_file_path_ios_no_application = temp  .. dest_file_path_relative

        file_info.dest_file_path_ios_no_application = dest_file_path_ios_no_application
    end

    return file_info
end

